import { test, expect } from '@playwright/test';

test.describe('File Upload Retry Without Re-selection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should allow retrying a failed upload without re-selecting the file', async ({ page }) => {
    // Verify upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeVisible();

    // Verify file input is visible and has a file selected
    const fileInput = page.getByLabel(/choose file/i);
    await expect(fileInput).toBeVisible();
    await expect(fileInput).toHaveValue('');

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify error message is visible
    const errorMessage = page.getByText(/file upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify upload progress bar is visible
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify retry button is enabled
    await expect(retryButton).toBeEnabled();

    // Click retry button
    await retryButton.click();

    // Verify file input still has the same file selected
    await expect(fileInput).toHaveValue('');

    // Verify error message is gone
    await expect(errorMessage).not.toBeVisible();

    // Verify upload progress bar is visible again
    await expect(progressBar).toBeVisible();

    // Verify upload button is visible again
    await expect(uploadButton).toBeVisible();

    // Verify retry button is disabled
    await expect(retryButton).not.toBeEnabled();

    // Verify success message is visible
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify file input is cleared
    await expect(fileInput).toHaveValue('');
  });

