    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeVisible();

    // Verify file input is visible and has a file selected
    const fileInput = page.getByLabel(/choose file/i);
    await expect(fileInput).toBeVisible();
    await expect(fileInput).toHaveValue('');

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify error message is visible
    const errorMessage = page.getByText(/file upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify upload progress bar is visible
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Click retry button
    await retryButton.click();

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();

    // Click retry button again
    await retryButton.click();

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();

    // Click retry button for the third time
    await retryButton.click();

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();

    // Verify upload button is still visible
    await expect(uploadButton).toBeVisible();

    // Verify retry button is still enabled
    await expect(retryButton).toBeEnabled();

    // Verify upload progress bar is still visible
    await expect(progressBar).toBeVisible();

